1	/**
2	 * @file weaknet_cli.cpp
3	 * @brief weaknet-cli 运行时配置命令行工具
4	 *
5	 * 薄封装 D-Bus 调用 SetMonitorParam / GetMonitorParam，
6	 * 所有业务逻辑（校验、原子提交、持久化）在服务端实现。
7	 *
8	 * 用法：
9	 *   weaknet-cli get <monitor>              # 查询监控器参数（JSON）
10	 *   weaknet-cli set <key> <value>          # 设置参数
11	 *   weaknet-cli list                       # 列出可用监控器
12	 *
13	 * 示例：
14	 *   weaknet-cli set rtt.interval 5s
15	 *   weaknet-cli get rtt
16	 *   weaknet-cli get all
17	 */
18	
19	#include <cstdio>
20	#include <cstdlib>
21	#include <cstring>
22	#include <string>
23	#include <vector>
24	#include <unistd.h>
25	
26	#include "weaknet_client.h"
27	
28	static void printUsage(const char* prog) {
29	    fprintf(stderr,
30	        "用法：\n"
31	        "  %s get <target>               # 查询参数（JSON，支持各监控器及 active_probe, edge, server, all）\n"
32	        "  sudo %s set <key> <value>     # 设置参数（需 root，如 rtt.interval 5s, active_probe.targets ...）\n"
33	        "  %s list                       # 列出所有可查询/配置的目标\n"
34	        "  %s monitor list|status [name] # 查看监控插件运行状态（仅限插件化监控器）\n"
35	        "  sudo %s monitor enable|disable|restart <name> # 启停监控插件（需 root）\n"
36	        "  sudo %s monitor save          # 保存运行时启停状态（需 root）\n"
37	        "  %s events [--device <addr>] [--type <TYPE>]\n"
38	        "         [--start <ms>] [--end <ms>] [--limit <N>]\n"
39	        "                                 # 查询无线设备事件（JSON，只读）\n"
40	        "  %s incidents [--state <STATE>]\n"
41	        "         [--start <ms>] [--end <ms>] [--limit <N>]\n"
42	        "                                 # 查询区域级异常事件 SiteIncident（JSON，只读）\n"
43	        "  %s bt-traffic [--device <addr>]\n"
44	        "         [--start <ms>] [--end <ms>] [--limit <N>]\n"
45	        "                                 # 查询工业蓝牙 HCI ACL 数据通道流量指标（JSON，只读）\n"
46	        "  %s diagnosis [--ai]            # 查询网络诊断事实（--ai 联动端侧 RAG + 板载 Qwen 深度分析）\n"
47	        "  %s experience                  # 查询当前网络体验权威快照（NetworkExperience JSON，只读）\n"
48	        "  sudo %s action <action_id> [<key> <val>] # 执行白名单安全排查动作（仅限 root）\n"
49	        "\n"
50	        "事件类型（--type）：LINK_DISCONNECTED, LINK_DEGRADED, DEVICE_APPEARED, ...\n"
51	        "区域事件状态（--state）：OPEN, ONGOING, RESOLVED\n"
52	        "时间均为 Unix 毫秒，0 或省略表示不限；limit 默认 100，上限 10000\n"
53	        "\n"
54	        "监控器与参数目标：\n"
55	        "  插件监控器（支持 get/set 及 monitor 启停）：\n"
56	        "        rtt, rssi, tcp_loss, traffic, quality, bluetooth, bt_events, bt_hci_traffic,\n"
57	        "        dns, wifi_loss, http_latency, process_profiler, tcp_retrans,\n"
58	        "        tcp_conn, skb_drop, tcp_connect\n"
59	        "  常驻服务/全局组件（仅支持 get/set 调参，非插件）：\n"
60	        "        active_probe, edge, server, all\n"
61	        "\n"
62	        "示例：\n"
63	        "  sudo %s set rtt.interval 5s\n"
64	        "  %s get rtt\n"
65	        "  %s bt-traffic\n"
66	        "  %s bt-traffic --device 20:23:00:00:00:01\n"
67	        "  %s diagnosis\n"
68	        "  %s experience\n"
69	        "  sudo %s action CHECK_RESOLVER_CONFIG\n"
70	        "  sudo %s action PROBE_PUBLIC_RESOLVER resolver 223.5.5.5\n"
71	        "  %s list\n",
72	        prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog, prog);
73	}
74	
75	static bool callSet(const char* key, const char* value) {
76	    char err[256];
77	    if (!weaknet_set_monitor_param(key, value, err, sizeof(err))) {
78	        fprintf(stderr, "Set failed: %s\n", err);
79	        return false;
80	    }
81	    printf("ok\n");
82	    return true;
83	}
84	
85	/// weaknet-cli events：查询规范化无线设备事件（只读）
86	/// 过滤参数全部可选；默认 limit=100（服务端上限 10000）
87	static bool callEvents(int argc, char** argv) {
88	    std::string device, type;
89	    int64_t start_ms = 0, end_ms = 0;
90	    int32_t limit = 100;
91	
92	    for (int i = 2; i < argc; ++i) {
93	        auto need = [&](const char* opt) -> const char* {
94	            if (i + 1 >= argc) {
95	                fprintf(stderr, "缺少 %s 的值\n", opt);
96	                return nullptr;
97	            }
98	            return argv[++i];
99	        };
100	        if (strcmp(argv[i], "--device") == 0) {
101	            const char* v = need("--device"); if (!v) return false;
102	            device = v;
103	        } else if (strcmp(argv[i], "--type") == 0) {
104	            const char* v = need("--type"); if (!v) return false;
105	            type = v;
106	        } else if (strcmp(argv[i], "--start") == 0) {
107	            const char* v = need("--start"); if (!v) return false;
108	            start_ms = strtoll(v, nullptr, 10);
109	        } else if (strcmp(argv[i], "--end") == 0) {
110	            const char* v = need("--end"); if (!v) return false;
111	            end_ms = strtoll(v, nullptr, 10);
112	        } else if (strcmp(argv[i], "--limit") == 0) {
113	            const char* v = need("--limit"); if (!v) return false;
114	            limit = static_cast<int32_t>(strtol(v, nullptr, 10));
115	        } else {
116	            fprintf(stderr, "未知参数: %s\n", argv[i]);
117	            return false;
118	        }
119	    }
120	
121	    // 上限 64KiB：limit 上限 10000 × 单条约 500B 最坏情况超出 64K，
122	    // 超出部分由服务端 limit 钳制约束（10000 条最坏约 5MB）——
123	    // 这里给 1MB 并提示用 --limit 收窄，避免栈上大数组
124	    std::vector<char> buf(1 << 20);
125	    char err[256];
126	    if (!weaknet_query_device_events(device.c_str(), type.c_str(),
127	                                     start_ms, end_ms, limit,
128	                                     buf.data(), buf.size(),
129	                                     err, sizeof(err))) {
130	        fprintf(stderr, "事件查询失败: %s\n", err);
131	        return false;
132	    }
133	    printf("%s\n", buf.data());
134	    return true;
135	}
136	
137	/// weaknet-cli incidents：查询区域级异常事件（只读，Phase 3a）
138	/// 过滤参数全部可选；默认 limit=100（服务端上限 10000）
139	static bool callIncidents(int argc, char** argv) {
140	    std::string state;
141	    int64_t start_ms = 0, end_ms = 0;
142	    int32_t limit = 100;
143	
144	    for (int i = 2; i < argc; ++i) {
145	        auto need = [&](const char* opt) -> const char* {
146	            if (i + 1 >= argc) {
147	                fprintf(stderr, "缺少 %s 的值\n", opt);
148	                return nullptr;
149	            }
150	            return argv[++i];
151	        };
152	        if (strcmp(argv[i], "--state") == 0) {
153	            const char* v = need("--state"); if (!v) return false;
154	            state = v;
155	        } else if (strcmp(argv[i], "--start") == 0) {
156	            const char* v = need("--start"); if (!v) return false;
157	            start_ms = strtoll(v, nullptr, 10);
158	        } else if (strcmp(argv[i], "--end") == 0) {
159	            const char* v = need("--end"); if (!v) return false;
160	            end_ms = strtoll(v, nullptr, 10);
161	        } else if (strcmp(argv[i], "--limit") == 0) {
162	            const char* v = need("--limit"); if (!v) return false;
163	            limit = static_cast<int32_t>(strtol(v, nullptr, 10));
164	        } else {
165	            fprintf(stderr, "未知参数: %s\n", argv[i]);
166	            return false;
167	        }
168	    }
169	
170	    // 与 callEvents 同一理由的 1MB 缓冲：区域事件单条含受影响设备清单，
171	    // 比设备事件更大；超出部分由服务端 limit 钳制约束。
172	    std::vector<char> buf(1 << 20);
173	    char err[256];
174	    if (!weaknet_query_site_incidents(state.c_str(), start_ms, end_ms, limit,
175	                                      buf.data(), buf.size(), err, sizeof(err))) {
176	        fprintf(stderr, "区域事件查询失败: %s\n", err);
177	        return false;
178	    }
179	    printf("%s\n", buf.data());
180	    return true;
181	}
182	
183	/// weaknet-cli bt-traffic：查询工业蓝牙 HCI ACL 数据通道历史指标（只读，Phase 1b）
184	static bool callBtTraffic(int argc, char** argv) {
185	    std::string device;
186	    int64_t start_ms = 0, end_ms = 0;
187	    int32_t limit = 100;
188	
189	    for (int i = 2; i < argc; ++i) {
190	        auto need = [&](const char* opt) -> const char* {
191	            if (i + 1 >= argc) {
192	                fprintf(stderr, "缺少 %s 的值\n", opt);
193	                return nullptr;
194	            }
195	            return argv[++i];
196	        };
197	        if (strcmp(argv[i], "--device") == 0) {
198	            const char* v = need("--device"); if (!v) return false;
199	            device = v;
200	        } else if (strcmp(argv[i], "--start") == 0) {
201	            const char* v = need("--start"); if (!v) return false;
202	            start_ms = strtoll(v, nullptr, 10);
203	        } else if (strcmp(argv[i], "--end") == 0) {
204	            const char* v = need("--end"); if (!v) return false;
205	            end_ms = strtoll(v, nullptr, 10);
206	        } else if (strcmp(argv[i], "--limit") == 0) {
207	            const char* v = need("--limit"); if (!v) return false;
208	            limit = static_cast<int32_t>(strtol(v, nullptr, 10));
209	        } else {
210	            fprintf(stderr, "未知参数: %s\n", argv[i]);
211	            return false;
212	        }
213	    }
214	
215	    std::vector<char> buf(1 << 20);
216	    char err[256];
217	    if (!weaknet_query_bt_data_path(device.c_str(), start_ms, end_ms, limit,
218	                                    buf.data(), buf.size(), err, sizeof(err))) {
219	        fprintf(stderr, "蓝牙数传指标查询失败: %s\n", err);
220	        return false;
221	    }
222	    printf("%s\n", buf.data());
223	    return true;
224	}
225	
226	static bool callLifecycle(const char* operation, const char* monitor) {
227	    char buf[8192];
228	    char err[256];
229	    bool ok = false;
230	    if (strcmp(operation, "status") == 0) {
231	        ok = monitor ? weaknet_get_monitor_status(monitor, buf, sizeof(buf), err, sizeof(err))
232	                     : weaknet_list_monitors(buf, sizeof(buf), err, sizeof(err));
233	    } else if (strcmp(operation, "enable") == 0) {
234	        ok = weaknet_enable_monitor(monitor, buf, sizeof(buf), err, sizeof(err));
235	    } else if (strcmp(operation, "disable") == 0) {
236	        ok = weaknet_disable_monitor(monitor, buf, sizeof(buf), err, sizeof(err));
237	    } else if (strcmp(operation, "restart") == 0) {
238	        ok = weaknet_restart_monitor(monitor, buf, sizeof(buf), err, sizeof(err));
239	    }
240	    if (ok) printf("%s\n", buf);
241	    else fprintf(stderr, "Monitor operation failed: %s\n", err);
242	    return ok;
243	}
244	
245	static bool callGet(const char* monitor) {
246	    char buf[8192];
247	    char err[256];
248	    if (!weaknet_get_monitor_param(monitor, buf, sizeof(buf), err, sizeof(err))) {
249	        fprintf(stderr, "Get failed: %s\n", err);
250	        return false;
251	    }
252	    printf("%s\n", buf);
253	    return true;
254	}
255	
256	static bool callSaveOverrides() {
257	    char buf[8192];
258	    char err[256];
259	    if (!weaknet_save_monitor_overrides(buf, sizeof(buf), err, sizeof(err))) {
260	        fprintf(stderr, "Save monitor overrides failed: %s\n", err);
261	        return false;
262	    }
263	    printf("%s\n", buf);
264	    return true;
265	}
266	
267	static bool callDiagnosis(bool enable_ai = false) {
268	    std::vector<char> buf(64 * 1024);
269	    char err[256];
270	    if (!weaknet_get_diagnosis(buf.data(), buf.size(), err, sizeof(err))) {
271	        fprintf(stderr, "GetDiagnosis 失败: %s\n", err);
272	        return false;
273	    }
274	
275	    if (!enable_ai) {
276	        printf("%s\n", buf.data());
277	        return true;
278	    }
279	
280	    // --ai 标志：调用本地端侧 Edge RAG (Python 脚本桥接板载 Qwen-0.5B 与知识库)
281	    std::vector<char> exp_buf(64 * 1024);
282	    if (!weaknet_get_network_experience(exp_buf.data(), exp_buf.size(), err, sizeof(err))) {
283	        fprintf(stderr, "获取网络体验快照失败，降级输出原始诊断: %s\n", err);
284	        printf("%s\n", buf.data());
285	        return true;
286	    }
287	
288	    // 优先调用 /home/radxa/weaknet/edge_network_rag.py
289	    const char* script_candidates[] = {
290	        "/home/radxa/weaknet/edge_network_rag.py",
291	        "./edge_network_rag.py",
292	        "../edge_network_rag.py"
293	    };
294	
295	    const char* chosen_script = nullptr;
296	    for (const char* path : script_candidates) {
297	        if (access(path, R_OK) == 0) {
298	            chosen_script = path;
299	            break;
300	        }
301	    }
302	
303	    if (!chosen_script) {
304	        fprintf(stderr, "⚠️ 未找到端侧 RAG 脚本，降级输出基础诊断\n");
305	        printf("%s\n", buf.data());
306	        return true;
307	    }
308	
309	    std::string cmd = std::string("python3 ") + chosen_script;
310	    FILE* pipe = popen(cmd.c_str(), "w");
311	    if (!pipe) {
312	        fprintf(stderr, "⚠️ 启动端侧 RAG 进程失败\n");
313	        printf("%s\n", buf.data());
314	        return true;
315	    }
316	
317	    fwrite(exp_buf.data(), 1, strlen(exp_buf.data()), pipe);
318	    pclose(pipe);
319	    return true;
320	}
321	
322	static bool callExperience() {
323	    std::vector<char> buf(64 * 1024);
324	    char err[256];
325	    if (!weaknet_get_network_experience(buf.data(), buf.size(), err, sizeof(err))) {
326	        fprintf(stderr, "GetNetworkExperience 失败: %s\n", err);
327	        return false;
328	    }
329	    printf("%s\n", buf.data());
330	    return true;
331	}
332	
333	static bool callAction(int argc, char** argv) {
334	    if (argc < 3 || argc > 5) {
335	        printUsage(argv[0]);
336	        return false;
337	    }
338	    const char* action_id = argv[2];
339	    const char* param_key = (argc >= 4) ? argv[3] : "";
340	    const char* param_val = (argc >= 5) ? argv[4] : "";
341	    std::vector<char> buf(64 * 1024);
342	    char err[256];
343	    if (!weaknet_execute_action(action_id, param_key, param_val, buf.data(), buf.size(), err, sizeof(err))) {
344	        fprintf(stderr, "ExecuteAction 失败: %s\n", err);
345	        return false;
346	    }
347	    printf("%s\n", buf.data());
348	    return true;
349	}
350	
351	int main(int argc, char** argv) {
352	    if (argc < 2) {
353	        printUsage(argv[0]);
354	        return 1;
355	    }
356	
357	    // 初始化客户端
358	    if (!weaknet_init()) {
359	        fprintf(stderr, "weaknet_init 失败\n");
360	        return 1;
361	    }
362	
363	    const char* cmd = argv[1];
364	    bool ok = false;
365	
366	    if (strcmp(cmd, "get") == 0) {
367	        if (argc != 3) {
368	            printUsage(argv[0]);
369	            return 1;
370	        }
371	        ok = callGet(argv[2]);
372	    } else if (strcmp(cmd, "set") == 0) {
373	        if (argc != 4) {
374	            printUsage(argv[0]);
375	            return 1;
376	        }
377	        ok = callSet(argv[2], argv[3]);
378	    } else if (strcmp(cmd, "monitor") == 0) {
379	        if (argc < 3 || argc > 4) {
380	            printUsage(argv[0]);
381	            return 1;
382	        }
383	        const char* operation = argv[2];
384	        const char* monitor = argc == 4 ? argv[3] : nullptr;
385	        if (strcmp(operation, "list") == 0 || strcmp(operation, "status") == 0) {
386	            if (strcmp(operation, "list") == 0 && monitor) {
387	                printUsage(argv[0]);
388	                return 1;
389	            }
390	            ok = callLifecycle(strcmp(operation, "list") == 0 ? "status" : operation, monitor);
391	        } else if (strcmp(operation, "save") == 0 && !monitor) {
392	            ok = callSaveOverrides();
393	        } else if ((strcmp(operation, "enable") == 0 || strcmp(operation, "disable") == 0 ||
394	                    strcmp(operation, "restart") == 0) && monitor) {
395	            ok = callLifecycle(operation, monitor);
396	        } else {
397	            printUsage(argv[0]);
398	            return 1;
399	        }
400	    } else if (strcmp(cmd, "events") == 0) {
401	        ok = callEvents(argc, argv);
402	    } else if (strcmp(cmd, "incidents") == 0) {
403	        ok = callIncidents(argc, argv);
404	    } else if (strcmp(cmd, "bt-traffic") == 0) {
405	        ok = callBtTraffic(argc, argv);
406	    } else if (strcmp(cmd, "diagnosis") == 0) {
407	        bool enable_ai = (argc >= 3 && strcmp(argv[2], "--ai") == 0);
408	        ok = callDiagnosis(enable_ai);
409	    } else if (strcmp(cmd, "experience") == 0) {
410	        ok = callExperience();
411	    } else if (strcmp(cmd, "action") == 0) {
412	        ok = callAction(argc, argv);
413	    } else if (strcmp(cmd, "list") == 0) {
414	        // 必须与 serializers 端的有效名集合保持一致（weaknet_config.cpp 的
415	        // serializeMonitorJson）。此前这里漏了 skb_drop / tcp_connect /
416	        // active_probe / edge——它们可以被 `set` 但 `list` 不显示，用户无从发现。
417	        printf("rtt\nrssi\ntcp_loss\ntraffic\nquality\n"
418	               "bluetooth\ndns\nwifi_loss\nhttp_latency\nprocess_profiler\n"
419	               "tcp_retrans\ntcp_conn\nskb_drop\ntcp_connect\ntcp_rtt\n"
420	               "active_probe\nedge\nserver\nall\n");
421	        ok = true;
422	    } else {
423	        fprintf(stderr, "未知命令: %s\n", cmd);
424	        printUsage(argv[0]);
425	        return 1;
426	    }
427	
428	    weaknet_cleanup();
429	    return ok ? 0 : 1;
430	}

