232	/**
233	 * @brief 内部统一信号发送函数（带重试）
234	 * @param signalName DBus 信号名（如 kSignalChanged、kSignalNetworkQualityChanged）
235	 * @param args       信号参数列表，每项为 {DBUS_TYPE_*, 值指针}
236	 * @param counter    事件计数器，便于接收方去重/排序
237	 * @return true 发送成功；false 三次重试全部失败
238	 *
239	 * 重试策略：最多 3 次，失败间隔 100ms。每次迭代：创建 signal → 追加参数 → send → flush。
240	 * 若 create signal 或 append 参数失败直接返回，不重试（属于编程错误而非网络抖动）。
241	 */
242	bool DbusService::sendSignalInternal(const std::string& signalName,
243	                                    const std::vector<std::pair<int, const void*>>& args,
244	                                    int32_t counter) {
245	    if (!ctx_ || !ctx_->connection) return false;
246	
247	    const int max_retries = 3;
248	    const int retry_delay_ms = 100;
249	
250	    for (int attempt = 0; attempt < max_retries; ++attempt) {
251	        DBusMessage* signal = dbus_message_new_signal(kObjectPath, kInterface, signalName.c_str());
252	        if (!signal) {
253	            LOG_ERROR(LogModule::DBUS, "sendSignalInternal: failed to create signal " << signalName);
254	            return false;
255	        }
256	
257	        DBusMessageIter iter;
258	        dbus_message_iter_init_append(signal, &iter);
259	
260	        // 按顺序逐个追加参数；args 中的指针在调用栈上，生命周期覆盖整个循环迭代
261	        for (const auto& [type, value] : args) {
262	            if (!dbus_message_iter_append_basic(&iter, type, value)) {
263	                LOG_ERROR(LogModule::DBUS, "sendSignalInternal: failed to append argument for " << signalName);
264	                dbus_message_unref(signal);
265	                return false;
266	            }
267	        }
268	
269	        bool ok = dbus_connection_send(ctx_->connection, signal, nullptr);
270	        dbus_connection_flush(ctx_->connection);
271	        dbus_message_unref(signal);
272	
273	        if (ok) {
274	            LOG_INFO(LogModule::DBUS, "sendSignalInternal: emitted " << signalName << " counter=" << counter);
275	            return true;
276	        }
277	
278	        LOG_WARNING(LogModule::DBUS, "sendSignalInternal(" << signalName << "): attempt " << attempt + 1
279	                    << " failed, retrying in " << retry_delay_ms << "ms");
280	
281	        if (attempt < max_retries - 1) {
282	            std::this_thread::sleep_for(std::chrono::milliseconds(retry_delay_ms));
283	        }
284	    }
285	
286	    LOG_ERROR(LogModule::DBUS, "sendSignalInternal(" << signalName << "): all " << max_retries << " attempts failed");
287	    return false;
288	}
