290	/**
291	 * @brief 发送通用 Changed 信号（带持久化）
292	 * @param message 信号载荷字符串
293	 * @param counter 事件计数器
294	 * @return true 发送成功
295	 *
296	 * 与 emitSpecificSignal 的区别：成功发送后额外将载荷序列化到文件，供重启恢复。
297	 * 内部持 send_mutex_，保证与其他信号发送的串行顺序。
298	 */
299	bool DbusService::emitChanged(const std::string& message, int32_t counter) {
300	    std::lock_guard<std::mutex> lock(send_mutex_);
301	
302	    // 构造参数列表
303	    const char* s = message.c_str();
304	    std::vector<std::pair<int, const void*>> args = {
305	        {DBUS_TYPE_STRING, &s},
306	        {DBUS_TYPE_INT32, &counter}
307	    };
308	
309	    bool ok = sendSignalInternal(kSignalChanged, args, counter);
310	
311	    // 仅在信号发送成功时持久化，避免文件与 DBus 状态不一致
312	    if (ok) {
313	        ChangedPayload payload{message, counter};
314	        std::string err;
315	        serializeChangedPayloadToFile(payload, kSignalSerializedFile, &err);
316	    }
317	
318	    return ok;
319	}
