323	/**
324	 * @brief 内部辅助：向调用方返回 string 数组
325	 * @param conn DBus 连接
326	 * @param msg 接收到的方法调用消息
327	 * @param arr 待返回的字符串列表
328	 * @return true 回复发送成功
329	 *
330	 * libdbus 中发送数组需要三步：open_container → append_basic × N → close_container。
331	 * 本方法将此模板封装，所有返回字符串列表的 handleXxx（如 ListInterfaces、
332	 * GetBluetoothDevices）都复用它。
333	 */
334	bool DbusService::replyStringArray(DBusConnection* conn, DBusMessage* msg, const std::vector<std::string>& arr) {
335	    DBusMessage* reply = dbus_message_new_method_return(msg);
336	    if (!reply) {
337	        LOG_ERROR(LogModule::DBUS, "replyStringArray: failed to create reply");
338	        return false;
339	    }
340	    DBusMessageIter iter;
341	    dbus_message_iter_init_append(reply, &iter);
342	    DBusMessageIter array_iter;
343	    // DBUS_TYPE_STRING_AS_STRING = "s"，用于告诉 dbus_message_iter_open_container 数组元素类型
344	    if (!dbus_message_iter_open_container(&iter, DBUS_TYPE_ARRAY, DBUS_TYPE_STRING_AS_STRING, &array_iter)) {
345	        LOG_ERROR(LogModule::DBUS, "replyStringArray: failed to open array container");
346	        dbus_message_unref(reply);
347	        return false;
348	    }
349	    for (const auto& s : arr) {
350	        const char* cs = s.c_str();
351	        if (!dbus_message_iter_append_basic(&array_iter, DBUS_TYPE_STRING, &cs)) {
352	            LOG_ERROR(LogModule::DBUS, "replyStringArray: failed to append string");
353	            dbus_message_iter_close_container(&iter, &array_iter);
354	            dbus_message_unref(reply);
355	            return false;
356	        }
357	    }
358	    if (!dbus_message_iter_close_container(&iter, &array_iter)) {
359	        LOG_ERROR(LogModule::DBUS, "replyStringArray: failed to close array container");
360	        dbus_message_unref(reply);
361	        return false;
362	    }
363	    bool ok = dbus_connection_send(conn, reply, nullptr);
364	    dbus_connection_flush(conn);
365	    dbus_message_unref(reply);
366	    return ok;
367	}
