385	/**
386	 * @brief DBus 方法实现：HealthCheck —— 返回当前网络质量评估
387	 * @param conn DBus 连接
388	 * @param msg 接收到的方法调用消息
389	 * @return true 回复发送成功
390	 *
391	 * 构造临时 NetworkQualityAssessor，对当前网卡快照做一次性评估，结果以字符串返回。
392	 * 不缓存 assessor，保证每次调用都是最新快照。
393	 */
394	bool DbusService::handleHealthCheck(DBusConnection* conn, DBusMessage* msg) {
395	    LOG_INFO(LogModule::DBUS, "handleHealthCheck called (CR-1 LegacyAdapter route)");
396	
397	    // 无上行时不编造网卡名（此前默认 "wlan0"）：返回的 interface 字段必须
398	    // 要么是真实在用的网卡，要么为空并由 overall=UNKNOWN 表达"无结论"。
399	    std::string active_iface;
400	    if (ctx_ && ctx_->weak_mgr) {
401	        auto opt = ctx_->weak_mgr->getCurrentUsingInterface();
402	        if (opt.has_value()) active_iface = opt.value();
403	    }
404	
405	    // 从 MetricsRegistry 拉取窗口并使用无状态 Evaluator 评估
406	    weaknet::NetworkExperience exp;
407	    int rtt_val = -1;
408	    double tcp_loss_val = 0.0;
409	    int rssi_val = -1000;
410	    double jitter_val = 0.0;
411	    double median_rtt_val = -1.0;
412	    std::string resp_reason = "";
413	
414	    // 无上行网卡时不查 registry（空串查不到任何样本），直接给显式 UNKNOWN：
415	    // 返回一份"不知道"比返回一份基于无关网卡的结论更诚实。
416	    if (ctx_ && ctx_->metrics_registry && !active_iface.empty()) {
417	        using namespace std::chrono_literals;
418	        // W2 单一事实源：HealthCheck **只读权威快照**，绝不重新 evaluate。
419	        // 此前本方法现场拉 metrics + 调 OverallPolicy，与 quality 线程、
420	        // history 线程构成三条结论可能不一致的评估路径（既有 bug）。
421	        // 现已彻底收敛至仅读取 AssessmentSnapshotStore 权威快照中的 experience：
422	        // overall、responsiveness SLE 结论与中位数证据均来自于同一份不可变快照。
423	        auto snap = ctx_->assessment_store.latest();
424	        if (snap) {
425	            const uint64_t cur_epoch = ctx_->dns_tracker ? ctx_->dns_tracker->currentBindingEpoch()
426	                                                         : ctx_->dns_binding_epoch.load();
427	            if (weaknet::AssessmentSnapshotStore::isCurrent(*snap,
428	                    ctx_->cfg.config_generation.load(), cur_epoch)) {
429	                exp = snap->experience;
430	            } else {
431	                // snapshot 过期：显式 UNKNOWN，等下一轮评估，不返回旧 profile 结论
432	                exp.iface = active_iface;
433	                exp.overall = weaknet::HealthState::UNKNOWN;
434	                exp.overall_coverage = weaknet::Coverage::NONE;
435	                exp.primary_issue = "stale_assessment";
436	            }
437	        } else {
438	            exp.iface = active_iface;
439	            exp.overall = weaknet::HealthState::UNKNOWN;
440	            exp.display_score = 50;
441	            exp.primary_issue = "no_assessment_yet";
442	        }
443	
444	        // 从快照的 responsiveness SLE 证据中提取 median_rtt_ms 与 reason
445	        resp_reason = exp.responsiveness.reason;
446	        for (const auto& ev : exp.responsiveness.evidence) {
447	            if (ev.metric == "median_rtt_ms") {
448	                median_rtt_val = ev.value;
449	            }
450	        }
451	
452	        auto latest_rtt = ctx_->metrics_registry->latest(active_iface, weaknet::MetricId::RTT_MS);
453	        if (latest_rtt.has_value() && latest_rtt->state == weaknet::MetricState::VALID) rtt_val = static_cast<int>(latest_rtt->value);
454	
455	        auto latest_loss = ctx_->metrics_registry->latest(active_iface, weaknet::MetricId::TCP_LOSS_RATE);
456	        if (latest_loss.has_value() && latest_loss->state == weaknet::MetricState::VALID) tcp_loss_val = latest_loss->value;
457	
458	        auto latest_rssi = ctx_->metrics_registry->latest(active_iface, weaknet::MetricId::RSSI_DBM);
459	        if (latest_rssi.has_value() && latest_rssi->state == weaknet::MetricState::VALID) rssi_val = static_cast<int>(latest_rssi->value);
460	
461	        auto latest_jitter = ctx_->metrics_registry->latest(active_iface, weaknet::MetricId::JITTER_MS);
462	        if (latest_jitter.has_value() && latest_jitter->state == weaknet::MetricState::VALID) jitter_val = latest_jitter->value;
463	    } else {
464	        exp.iface = active_iface;
465	        exp.overall = weaknet::HealthState::UNKNOWN;
466	        exp.display_score = 50;
467	    }
468	
469	    std::string reply_text = weaknet::LegacyAdapter::toHealthCheckJson(exp, rtt_val, tcp_loss_val, rssi_val, jitter_val, median_rtt_val, resp_reason);
470	
471	    DBusMessage* reply = dbus_message_new_method_return(msg);
472	    if (!reply) return false;
473	    DBusMessageIter args;
474	    dbus_message_iter_init_append(reply, &args);
475	    const char* s = reply_text.c_str();
476	    if (!dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &s)) { dbus_message_unref(reply); return false; }
477	    if (!dbus_connection_send(conn, reply, nullptr)) { dbus_message_unref(reply); return false; }
478	    dbus_connection_flush(conn);
479	    dbus_message_unref(reply);
480	    return true;
481	}
