524	/**
525	 * @brief 校验调用方为 root (UID 0)，否则回 ACCESS_DENIED。
526	 *
527	 * 覆盖面：一切能改变设备行为的写方法。理由见头文件声明。
528	 * 取不到 sender 或 UID 查询失败时**保守拒绝**——把"无法确定身份"当作非特权，
529	 * 而不是放行。
530	 */
531	bool DbusService::requireRootCaller(DBusConnection* conn, DBusMessage* msg,
532	                                    const char* method_name) {
533	    const char* sender = dbus_message_get_sender(msg);
534	    unsigned long caller_uid = 1000;  // 默认按普通用户处理
535	    DBusError uid_err;
536	    dbus_error_init(&uid_err);
537	    if (sender) {
538	        caller_uid = dbus_bus_get_unix_user(conn, sender, &uid_err);
539	        if (dbus_error_is_set(&uid_err)) {
540	            LOG_WARNING(LogModule::DBUS, method_name
541	                        << ": failed to get caller UID: " << uid_err.message);
542	            dbus_error_free(&uid_err);
543	            caller_uid = 1000;
544	        }
545	    }
546	    if (caller_uid == 0) return true;
547	
548	    LOG_ERROR(LogModule::DBUS, method_name << " rejected: caller UID " << caller_uid
549	              << " != 0 (permission denied)");
550	    DBusMessage* reply = dbus_message_new_error(msg, DBUS_ERROR_ACCESS_DENIED,
551	        "Permission denied: only root (UID 0) is authorized to modify WeakNet state");
552	    if (reply) {
553	        dbus_connection_send(conn, reply, nullptr);
554	        dbus_message_unref(reply);
555	    }
556	    return false;
557	}
