559	/**
560	 * @brief DBus 方法实现：ExecuteAction —— 安全执行白名单建议动作
561	 */
562	bool DbusService::handleExecuteAction(DBusConnection* conn, DBusMessage* msg) {
563	    LOG_INFO(LogModule::DBUS, "handleExecuteAction called");
564	
565	    // 严格安全防线：校验调用者 UID 必须为 root (UID 0)，防止非特权本地用户通过系统总线触发特权网络动作
566	    if (!requireRootCaller(conn, msg, "ExecuteAction")) return false;
567	
568	    DBusError err;
569	    dbus_error_init(&err);
570	    const char* action_id = nullptr;
571	    const char* param_key = nullptr;
572	    const char* param_val = nullptr;
573	
574	    // 支持参数格式：action_id, param_key, param_val (空则忽略)
575	    if (!dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &action_id,
576	                               DBUS_TYPE_STRING, &param_key,
577	                               DBUS_TYPE_STRING, &param_val,
578	                               DBUS_TYPE_INVALID)) {
579	        dbus_error_free(&err);
580	        // 也尝试仅单个 action_id
581	        dbus_error_init(&err);
582	        if (!dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &action_id, DBUS_TYPE_INVALID)) {
583	            dbus_error_free(&err);
584	            DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Invalid arguments: expected action_id");
585	            dbus_connection_send(conn, reply, nullptr);
586	            dbus_message_unref(reply);
587	            return false;
588	        }
589	    }
590	
591	    std::map<std::string, std::string> params;
592	    if (param_key && strlen(param_key) > 0 && param_val) {
593	        params[param_key] = param_val;
594	    }
595	
596	    // 所有内插字符串一律经 escapeJsonString：命令输出（如 /etc/resolv.conf 的
597	    // 注释与换行、ip route 的缩进）与 caller 提供的 action_id 都可能含引号或
598	    // 控制字符，裸拼进 JSON 字面量会产出客户端无法解析的畸形 JSON。
599	    std::string result_json;
600	    if (ctx_ && ctx_->action_registry) {
601	        auto val_res = ctx_->action_registry->validate(action_id, params);
602	        if (!val_res.ok) {
603	            result_json = "{\"success\":false,\"error\":\""
604	                        + weaknet_utils::escapeJsonString(val_res.error) + "\"}";
605	        } else {
606	            auto spec_opt = ctx_->action_registry->buildExecSpec(action_id, params);
607	            if (!spec_opt.has_value()) {
608	                result_json = "{\"success\":false,\"error\":\"Failed to build ExecSpec\"}";
609	            } else {
610	                auto exec_res = weaknet::ActionRegistry::safeExec(*spec_opt);
611	                result_json = "{\"success\":" + std::string(exec_res.exit_code == 0 ? "true" : "false")
612	                            + ",\"exit_code\":" + std::to_string(exec_res.exit_code)
613	                            + ",\"stdout\":\""
614	                            + weaknet_utils::escapeJsonString(exec_res.stdout_output.substr(0, 500)) + "\""
615	                            + ",\"error\":\""
616	                            + weaknet_utils::escapeJsonString(exec_res.error) + "\"}";
617	            }
618	        }
619	    } else {
620	        result_json = "{\"success\":false,\"error\":\"ActionRegistry not initialized\"}";
621	    }
622	
623	    DBusMessage* reply = dbus_message_new_method_return(msg);
624	    if (!reply) return false;
625	    DBusMessageIter args;
626	    dbus_message_iter_init_append(reply, &args);
627	    const char* s = result_json.c_str();
628	    if (!dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &s)) { dbus_message_unref(reply); return false; }
629	    if (!dbus_connection_send(conn, reply, nullptr)) { dbus_message_unref(reply); return false; }
630	    dbus_connection_flush(conn);
631	    dbus_message_unref(reply);
632	    return true;
633	}
