680	/**
681	 * @brief DBus 方法实现：Ping —— 对指定主机执行 ICMP 探测
682	 * @param conn DBus 连接
683	 * @param msg 接收到的方法调用消息（参数：hostname 字符串）
684	 * @return true 回复发送成功
685	 *
686	 * 步骤：解析 hostname → 找到当前上网网卡 → 调用 NetPing::ping()（3 秒超时）→ 回复结果字符串。
687	 * 任何环节失败都返回 DBus error 消息而非空回复。
688	 */
689	bool DbusService::handlePing(DBusConnection* conn, DBusMessage* msg) {
690	    LOG_INFO(LogModule::DBUS, "handlePing called");
691	
692	    // Ping 方法能够强制主机在生产接口向任意地址发射网络探测报文，
693	    // 且同步等待超时（最多 3 秒），会阻塞单一的 D-Bus 分发线程。
694	    // 为防任意本地用户利用其饿死系统或发起未授权的主动探测，统一收紧至 root 权限。
695	    if (!requireRootCaller(conn, msg, "Ping")) return false;
696	
697	    // 解析参数：目标主机名
698	    DBusError err;
699	    dbus_error_init(&err);
700	    const char* hostname = nullptr;
701	
702	    if (!dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &hostname, DBUS_TYPE_INVALID)) {
703	        LOG_ERROR(LogModule::DBUS, "Ping method error: " << err.message);
704	        dbus_error_free(&err);
705	
706	        // 发送错误回复
707	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Invalid arguments");
708	        dbus_connection_send(conn, reply, nullptr);
709	        dbus_message_unref(reply);
710	        return false;
711	    }
712	
713	    if (!hostname || strlen(hostname) == 0) {
714	        LOG_ERROR(LogModule::DBUS, "Ping method error: empty hostname");
715	
716	        // 发送错误回复
717	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Empty hostname");
718	        dbus_connection_send(conn, reply, nullptr);
719	        dbus_message_unref(reply);
720	        return false;
721	    }
722	
723	    LOG_INFO(LogModule::DBUS, "Ping request for host: " << hostname);
724	
725	    // 获取当前上网网卡（接口列表唯一事实源 = WeakNetMgr::current_interfaces_）
726	    std::string currentIface;
727	    {
728	        auto interfaces = ctx_->weak_mgr->getCurrentInterfaces();
729	        for (const auto& net : interfaces) {
730	            if (net.usingNow()) {
731	                currentIface = net.ifName();
732	                break;
733	            }
734	        }
735	    }
736	
737	    if (currentIface.empty()) {
738	        LOG_ERROR(LogModule::DBUS, "Ping method error: no active interface found");
739	
740	        // 发送错误回复
741	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "No active network interface");
742	        dbus_connection_send(conn, reply, nullptr);
743	        dbus_message_unref(reply);
744	        return false;
745	    }
746	
747	    LOG_INFO(LogModule::DBUS, "Using interface: " << currentIface << " for ping to " << hostname);
748	
749	    // 调用NetPing进行ping测试
750	    auto pingInstance = NetPing::getInstance();
751	    int pingResult = pingInstance->ping(hostname, currentIface, 3000); // 3秒超时
752	
753	    // 构建回复消息
754	    DBusMessage* reply = dbus_message_new_method_return(msg);
755	    if (!reply) {
756	        LOG_ERROR(LogModule::DBUS, "Failed to create ping reply message");
757	        return false;
758	    }
759	
760	    DBusMessageIter args;
761	    dbus_message_iter_init_append(reply, &args);
762	
763	    // 根据 ping 返回值（≥0 为 RTT ms，<0 为错误码）构造人类可读字符串
764	    std::string result;
765	    if (pingResult >= 0) {
766	        result = std::string("PING ") + hostname + " via " + currentIface + ": " + std::to_string(pingResult) + "ms";
767	        LOG_INFO(LogModule::DBUS, "Ping successful: " << result);
768	    } else {
769	        result = std::string("PING ") + hostname + " via " + currentIface + ": FAILED (error code: " + std::to_string(pingResult) + ")";
770	        LOG_INFO(LogModule::DBUS, "Ping failed: " << result);
771	    }
772	
773	    const char* resultStr = result.c_str();
774	    if (!dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &resultStr)) {
775	        LOG_ERROR(LogModule::DBUS, "Failed to append ping result to reply");
776	        dbus_message_unref(reply);
777	        return false;
778	    }
779	
780	    // 发送回复
781	    bool ok = dbus_connection_send(conn, reply, nullptr);
782	    dbus_connection_flush(conn);
783	    dbus_message_unref(reply);
784	
785	    LOG_INFO(LogModule::DBUS, "Ping reply sent: " << (ok ? "success" : "failed"));
786	    return ok;
787	}
