793	/**
794	 * @brief DBus 方法实现：GetBluetoothDevices —— 返回蓝牙设备列表
795	 * @param conn DBus 连接
796	 * @param msg 接收到的方法调用消息
797	 * @return true 回复发送成功
798	 *
799	 * 每个设备编码为一条 "MAC|Name|RSSI|Connected|Type|Level" 字符串，
800	 * 所有设备组成 string 数组返回。BtMonitor 未初始化时返回空数组。
801	 */
802	bool DbusService::handleGetBluetoothDevices(DBusConnection* conn, DBusMessage* msg) {
803	    LOG_INFO(LogModule::DBUS, "handleGetBluetoothDevices called");
804	
805	    std::vector<std::string> lines;
806	    {
807	        std::shared_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
808	        BtMonitor* monitor = ctx_ ? ctx_->bt_monitor : nullptr;
809	        if (!monitor) {
810	            // 无蓝牙监测器 → 返回空数组。必须构造合法的空 DBus 数组容器，不能跳过 open_container
811	            DBusMessage* reply = dbus_message_new_method_return(msg);
812	            if (reply) {
813	                DBusMessageIter iter;
814	                dbus_message_iter_init_append(reply, &iter);
815	                DBusMessageIter arr;
816	                dbus_message_iter_open_container(&iter, DBUS_TYPE_ARRAY, DBUS_TYPE_STRING_AS_STRING, &arr);
817	                dbus_message_iter_close_container(&iter, &arr);
818	                dbus_connection_send(conn, reply, nullptr);
819	                dbus_connection_flush(conn);
820	                dbus_message_unref(reply);
821	            }
822	            return true;
823	        }
824	
825	        // 获取设备列表，格式化为 "MAC|Name|RSSI|Connected|Type|Level" 字符串
826	        auto devices = monitor->getDevices();
827	        lines.reserve(devices.size());
828	        for (const auto& dev : devices) {
829	            // 字段顺序固定：MAC → 显示名（优先 alias，无则 name）→ RSSI dBm → 连接标记 → 类型 → RSSI 等级
830	            std::string line = dev.macAddress + "|"
831	                + (dev.name.empty() ? dev.alias : dev.name) + "|"
832	                + std::to_string(dev.rssiDbm) + "|"
833	                + (dev.connected ? "1" : "0") + "|"
834	                + (dev.deviceType == BtDeviceType::BLE ? "BLE" :
835	                   dev.deviceType == BtDeviceType::Classic ? "Classic" : "Dual") + "|"
836	                + dev.rssiLevel();
837	            lines.push_back(line);
838	        }
839	    }
840	    return replyStringArray(conn, msg, lines);
841	}
