885	/**
886	 * @brief DBus 方法实现：GetBluetoothAudioQuality —— 返回指定设备音频质量与 eBPF 融合诊断 JSON
887	 * @param conn DBus 连接
888	 * @param msg  接收到的方法调用消息（可选参数 string: macAddress）
889	 */
890	bool DbusService::handleGetBluetoothAudioQuality(DBusConnection* conn, DBusMessage* msg) {
891	    LOG_INFO(LogModule::DBUS, "handleGetBluetoothAudioQuality called");
892	    DBusMessage* reply = dbus_message_new_method_return(msg);
893	    if (!reply) return false;
894	
895	    std::string targetMac;
896	    DBusError err;
897	    dbus_error_init(&err);
898	    const char* reqMac = nullptr;
899	    if (dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &reqMac, DBUS_TYPE_INVALID)) {
900	        if (reqMac) targetMac = reqMac;
901	    } else {
902	        dbus_error_free(&err);
903	    }
904	
905	    std::string jsonResult;
906	    {
907	        std::shared_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
908	        BtMonitor* monitor = ctx_ ? ctx_->bt_monitor : nullptr;
909	
910	        if (!monitor || !monitor->isInitialized()) {
911	            jsonResult = "{\"error\":\"Bluetooth monitor not available or uninitialized\",\"mac\":\"" + targetMac + "\"}";
912	        } else {
913	            // 如果未指定 targetMac，则尝试寻找第一个已连接设备或已有的 transport 设备
914	            if (targetMac.empty()) {
915	                auto transports = monitor->getAudioTransports();
916	                if (!transports.empty()) {
917	                    targetMac = transports.front().deviceMac;
918	                } else {
919	                    auto connected = monitor->getConnectedDevices();
920	                    if (!connected.empty()) {
921	                        targetMac = connected.front().macAddress;
922	                    }
923	                }
924	            }
925	
926	            if (targetMac.empty()) {
927	                jsonResult = "{\"error\":\"No active Bluetooth device specified or found\",\"mac\":\"\"}";
928	            } else {
929	                BtAudioFusionResult fusion;
930	                bool found = monitor->getAudioFusionResult(targetMac, &fusion);
931	                if (!found) {
932	                    // 如果无 transport，仍尝试获取设备基本信息
933	                    BtDeviceInfo devInfo;
934	                    bool devFound = monitor->getDevice(targetMac, &devInfo);
935	                    jsonResult = "{\"mac\":\"" + targetMac + "\","
936	                                 "\"name\":\"" + (devFound ? (devInfo.name.empty() ? devInfo.alias : devInfo.name) : "unknown") + "\","
937	                                 "\"connected\":" + (devFound && devInfo.connected ? "true" : "false") + ","
938	                                 "\"audio_transport_active\":false,"
939	                                 "\"quality_score\":0.0,"
940	                                 "\"quality_level\":\"unknown\","
941	                                 "\"diagnostic\":\"No A2DP media transport detected for this device\"}";
942	                } else {
943	                    std::ostringstream oss;
944	                    oss << "{"
945	                        << "\"mac\":\"" << fusion.deviceMac << "\","
946	                        << "\"active\":" << (fusion.isActive ? "true" : "false") << ","
947	                        << "\"effective_active\":" << (fusion.effectiveActive ? "true" : "false") << ","
948	                        << "\"suspected_stall\":" << (fusion.suspectedStall ? "true" : "false") << ","
949	                        << "\"quality_score\":" << fusion.qualityScore << ","
950	                        << "\"quality_level\":\"" << fusion.level << "\","
951	                        << "\"active_ratio\":" << fusion.activeRatio << ","
952	                        << "\"ebpf_correction\":" << fusion.ebpfCorrection << ","
953	                        << "\"bytes_per_sec\":" << fusion.bytesPerSec << ","
954	                        << "\"max_gap_ms\":" << fusion.maxGapMs << ","
955	                        << "\"ebpf_available\":" << (fusion.ebpfAvailable ? "true" : "false") << ","
956	                        << "\"diagnostic\":\"" << fusion.diagnostic << "\""
957	                        << "}";
958	                    jsonResult = oss.str();
959	                }
960	            }
961	        }
962	    }
963	
964	    DBusMessageIter args;
965	    dbus_message_iter_init_append(reply, &args);
966	    const char* s = jsonResult.c_str();
967	    dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &s);
968	    dbus_connection_send(conn, reply, nullptr);
969	    dbus_connection_flush(conn);
970	    dbus_message_unref(reply);
971	    return true;
972	}
