1000	/**
1001	 * @brief DBus 方法实现：GetNetworkExperience —— 返回权威评估快照（schema v2）
1002	 *
1003	 * **只读 snapshot，绝不重新 evaluate**（W2 单一事实源）：
1004	 * quality 线程是唯一 evaluator 执行点；本方法只序列化 stabilizer 后的
1005	 * 最终结论。实测此前三条评估路径（quality/history/HealthCheck）各自拉
1006	 * 不同 metrics、结论可能不一致 —— 该 bug 由本方法杜绝。
1007	 *
1008	 * 生命周期边界：
1009	 *   - 尚无第一份 snapshot → 显式 UNKNOWN(no_assessment_yet)，不返回空对象
1010	 *   - config_generation / network_epoch 与当前不符 → 旧 snapshot 失效，
1011	 *     同样返回 UNKNOWN(stale_assessment)，等下一轮评估
1012	 */
1013	bool DbusService::handleGetNetworkExperience(DBusConnection* conn, DBusMessage* msg) {
1014	    LOG_INFO(LogModule::DBUS, "handleGetNetworkExperience called (W2 read-only snapshot)");
1015	
1016	    std::string jsonResult;
1017	    auto snap = ctx_ ? ctx_->assessment_store.latest() : nullptr;
1018	    bool stale = false;
1019	    if (snap) {
1020	        // 配置代/网络代与当前不符 → 旧 snapshot 失效
1021	        const uint64_t cur_epoch = ctx_->dns_tracker ? ctx_->dns_tracker->currentBindingEpoch()
1022	                                                     : ctx_->dns_binding_epoch.load();
1023	        if (!weaknet::AssessmentSnapshotStore::isCurrent(*snap,
1024	                ctx_->cfg.config_generation.load(), cur_epoch)) {
1025	            stale = true;
1026	        }
1027	    }
1028	
1029	    if (!snap) {
1030	        jsonResult = "{\"schema_version\":2,\"state\":\"UNKNOWN\","
1031	                     "\"coverage\":\"NONE\",\"reason\":\"no_assessment_yet\"}";
1032	    } else if (stale) {
1033	        jsonResult = "{\"schema_version\":2,\"state\":\"UNKNOWN\","
1034	                     "\"coverage\":\"NONE\",\"reason\":\"stale_assessment\","
1035	                     "\"note\":\"waiting for next evaluation with current config/epoch\"}";
1036	    } else {
1037	        jsonResult = weaknet::LegacyAdapter::toExperienceJsonV2(snap->experience);
1038	    }
1039	
1040	    DBusMessage* reply = dbus_message_new_method_return(msg);
1041	    if (!reply) return false;
1042	    DBusMessageIter args;
1043	    dbus_message_iter_init_append(reply, &args);
1044	    const char* s = jsonResult.c_str();
1045	    if (!dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &s)) {
1046	        dbus_message_unref(reply);
1047	        return false;
1048	    }
1049	    dbus_connection_send(conn, reply, nullptr);
1050	    dbus_connection_flush(conn);
1051	    dbus_message_unref(reply);
1052	    return true;
1053	}
