1339	/**
1340	 * @brief DBus 方法实现：GetEbpfMonitorHealth —— 返回所有 eBPF monitor 健康状态（JSON）
1341	 * @return JSON 字符串,结构: {"monitors":[{name,state,available,healthy,map_reads,map_read_errors,samples,average_read_time_us,status}, ...]}
1342	 *
1343	 * 遍历 8 个实现了 IEbpfMonitor 接口的组件（DNS/Wi-Fi 丢包/HTTP 延迟/进程 profiling/
1344	 * TCP 重传/TCP 连接统计/Socket 丢包/蓝牙音频），每个采集 health() 和 metrics()。
1345	 * 蓝牙音频分析器为可选项：对象未创建时输出一份 "uninitialized" 占位条目，
1346	 * 保证 JSON 始终包含全部项且不出现空指针解引用。
1347	 */
1348	bool DbusService::handleGetEbpfMonitorHealth(DBusConnection* conn, DBusMessage* msg) {
1349	    LOG_INFO(LogModule::DBUS, "handleGetEbpfMonitorHealth called");
1350	    if (!ctx_) {
1351	        DBusMessage* error = dbus_message_new_error(msg, "com.example.WeakNet.Error", "monitor context unavailable");
1352	        if (error) { dbus_connection_send(conn, error, nullptr); dbus_message_unref(error); }
1353	        return false;
1354	    }
1355	
1356	    // 每个 monitor 独立输出；停止或初始化失败的对象以 unavailable 占位。
1357	    const auto monitorState = [this](const char* name) {
1358	        MonitorStatus status;
1359	        return ctx_->monitor_manager && ctx_->monitor_manager->status(name, &status)
1360	            ? std::string(monitorStateName(status.state)) : std::string("unavailable");
1361	    };
1362	
1363	    std::ostringstream json;
1364	    json << "{\"monitors\":[";
1365	    {
1366	        std::shared_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
1367	        const IEbpfMonitor* bt_audio = nullptr;
1368	        if (ctx_->bt_monitor) {
1369	            bt_audio = ctx_->bt_monitor->audioAnalyzer();
1370	        }
1371	
1372	        const std::vector<std::pair<const char*, const IEbpfMonitor*>> monitors = {
1373	            {"DnsMonitor", static_cast<const IEbpfMonitor*>(ctx_->dns_monitor)},
1374	            {"WifiPacketLossMonitor", static_cast<const IEbpfMonitor*>(ctx_->wifi_loss_monitor)},
1375	            {"HttpLatencyMonitor", static_cast<const IEbpfMonitor*>(ctx_->http_latency_monitor)},
1376	            {"ProcessNetProfiler", static_cast<const IEbpfMonitor*>(ctx_->process_net_profiler)},
1377	            {"TcpRetransMonitor", static_cast<const IEbpfMonitor*>(ctx_->tcp_retrans_monitor)},
1378	            {"TcpConnMonitor", static_cast<const IEbpfMonitor*>(ctx_->tcp_conn_monitor)},
1379	            {"SkbDropMonitor", static_cast<const IEbpfMonitor*>(ctx_->skb_drop_monitor)},
1380	            {"TcpRttMonitor", static_cast<const IEbpfMonitor*>(ctx_->tcp_rtt_monitor)},
1381	            {"BtAudioAnalyzer", bt_audio},
1382	            {"BtDataPathAnalyzer", static_cast<const IEbpfMonitor*>(ctx_->bt_hci_analyzer)}
1383	        };
1384	
1385	        // 手工拼接 JSON：项目不依赖 JSON 库，字段名和字符串值都要做 JSON 转义
1386	        for (size_t i = 0; i < monitors.size(); ++i) {
1387	            if (i > 0) json << ",";
1388	            if (!monitors[i].second) {
1389	                json << "{\"name\":\"" << weaknet_utils::escapeJsonString(monitors[i].first)
1390	                     << "\",\"state\":\"" << monitorState(monitors[i].first)
1391	                     << "\",\"available\":false,\"healthy\":false,\"last_successful_sample_ns\":0,\"consecutive_errors\":0"
1392	                     << ",\"total_errors\":0,\"attached_probes\":0,\"map_reads\":0,\"map_read_errors\":0"
1393	                     << ",\"samples\":0,\"total_read_time_us\":0,\"average_read_time_us\":0"
1394	                     << ",\"last_error\":\"monitor not running\",\"status\":\"unavailable\"}";
1395	                continue;
1396	            }
1397	            const auto health = monitors[i].second->health();
1398	            const auto metrics = monitors[i].second->metrics();
1399	            const auto key_stats = monitors[i].second->keyStatsSnapshot();
1400	            json << "{\"name\":\"" << weaknet_utils::escapeJsonString(health.name)
1401	                 << "\",\"state\":\"" << ebpfMonitorStateName(health.state)
1402	                 << "\",\"available\":" << (health.available ? "true" : "false")
1403	                 << ",\"healthy\":" << (health.healthy ? "true" : "false")
1404	                 << ",\"last_successful_sample_ns\":" << health.lastSuccessfulSampleNs
1405	                 << ",\"consecutive_errors\":" << health.consecutiveErrors
1406	                 << ",\"total_errors\":" << health.totalErrors
1407	                 << ",\"attached_probes\":" << metrics.attachedProbes
1408	                 << ",\"map_reads\":" << metrics.mapReads
1409	                 << ",\"map_read_errors\":" << metrics.mapReadErrors
1410	                 << ",\"samples\":" << metrics.samples
1411	                 << ",\"total_read_time_us\":" << metrics.totalReadTimeUs
1412	                 << ",\"average_read_time_us\":" << metrics.averageReadTimeUs
1413	                 << ",\"last_error\":\"" << weaknet_utils::escapeJsonString(metrics.lastError)
1414	                 << "\",\"status\":\"" << weaknet_utils::escapeJsonString(health.status)
1415	                 << "\"";
1416	            // 驱逐可见性：只有启用了 PerKeyCounterTracker 的监控器会产出非零数据。
1417	            // 字段存在与否比 always-zero 更能区分"未启用"与"本轮无变化"。
1418	            if (key_stats.max_entries > 0 || key_stats.entries > 0) {
1419	                json << ",\"eviction\":{\"new_keys\":" << key_stats.new_keys
1420	                     << ",\"disappeared_keys\":" << key_stats.disappeared_keys
1421	                     << ",\"reset_keys\":" << key_stats.reset_keys
1422	                     << ",\"entries\":" << key_stats.entries
1423	                     << ",\"max_entries\":" << key_stats.max_entries
1424	                     << ",\"watermark_pct\":" << key_stats.watermark_pct
1425	                     << ",\"eviction_limited\":" << (key_stats.eviction_limited ? "true" : "false")
1426	                     << "}";
1427	            }
1428	            json << "}";
1429	        }
1430	    }
1431	    json << "]}";
1432	
1433	    DBusMessage* reply = dbus_message_new_method_return(msg);
1434	    if (!reply) return false;
1435	    DBusMessageIter args;
1436	    dbus_message_iter_init_append(reply, &args);
1437	    const std::string result = json.str();
1438	    const char* value = result.c_str();
1439	    dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &value);
1440	    bool ok = dbus_connection_send(conn, reply, nullptr);
1441	    dbus_connection_flush(conn);
1442	    dbus_message_unref(reply);
1443	    return ok;
1444	}
