1446	/**
1447	 * @brief DBus 方法实现：GetHistory —— 从数据库查询历史记录
1448	 * @param conn DBus 连接
1449	 * @param msg 接收到的方法调用消息（参数：interface[可选]、start[可选]、end[可选]、limit[可选，默认 100]）
1450	 * @return true 回复发送成功；DB 返回值是 JSON 字符串（或错误 JSON）
1451	 *
1452	 * 参数解析采用"逐次 dbus_message_iter_next"风格：先按约定顺序迭代，缺省的用默认值填充。
1453	 * 任何参数类型都没有严格强制——缺失或类型不符就跳过，用默认值。
1454	 */
1455	bool DbusService::handleGetHistory(DBusConnection* conn, DBusMessage* msg) {
1456	    LOG_INFO(LogModule::DBUS, "handleGetHistory called");
1457	
1458	    // 解析收到的消息必须用 dbus_message_iter_init（读迭代器）；
1459	    // init_append 是写迭代器，对入站消息使用会触发 libdbus 断言/未定义行为。
1460	    // init 返回 FALSE 表示消息无参数，全部走缺省值。
1461	    std::string iface_filter, start_time, end_time;
1462	    int32_t limit = 100;
1463	
1464	    DBusMessageIter args;
1465	    const bool hasArgs = dbus_message_iter_init(msg, &args) == TRUE;
1466	    if (hasArgs) {
1467	    // 参数 1: interface (string)，可缺省
1468	    if (dbus_message_iter_get_arg_type(&args) == DBUS_TYPE_STRING) {
1469	        const char* val = nullptr;
1470	        dbus_message_iter_get_basic(&args, &val);
1471	        if (val) iface_filter = val;
1472	    }
1473	    if (dbus_message_iter_next(&args)) {
1474	        // 参数 2: start (string)
1475	        if (dbus_message_iter_get_arg_type(&args) == DBUS_TYPE_STRING) {
1476	            const char* val = nullptr;
1477	            dbus_message_iter_get_basic(&args, &val);
1478	            if (val) start_time = val;
1479	        }
1480	    }
1481	    if (dbus_message_iter_next(&args)) {
1482	        // 参数 3: end (string)
1483	        if (dbus_message_iter_get_arg_type(&args) == DBUS_TYPE_STRING) {
1484	            const char* val = nullptr;
1485	            dbus_message_iter_get_basic(&args, &val);
1486	            if (val) end_time = val;
1487	        }
1488	    }
1489	    if (dbus_message_iter_next(&args)) {
1490	        // 参数 4: limit (int32)
1491	        if (dbus_message_iter_get_arg_type(&args) == DBUS_TYPE_INT32) {
1492	            dbus_message_iter_get_basic(&args, &limit);
1493	        }
1494	    }
1495	    }  // hasArgs
1496	
1497	    // 钳制 limit：该接口对本地任意用户开放（见 com.example.WeakNet.conf 的
1498	    // default 上下文），而 SQLite 把负 LIMIT 解释为"无上限"。若把 -1 直接
1499	    // 透传，queryHistory 会把整张历史表拼成一个 std::ostringstream 并作为
1500	    // 单条 D-Bus 字符串回发，足以耗尽内存或触发 128MB 消息上限。
1501	    // 0 同样危险（静默返回空集），故一并归一为下限 1。
1502	    constexpr int32_t kMaxHistoryLimit = 10000;
1503	    if (limit <= 0) {
1504	        LOG_WARNING(LogModule::DBUS, "GetHistory limit=" << limit
1505	                    << " is non-positive; clamped to 1");
1506	        limit = 1;
1507	    } else if (limit > kMaxHistoryLimit) {
1508	        LOG_WARNING(LogModule::DBUS, "GetHistory limit=" << limit
1509	                    << " exceeds cap; clamped to " << kMaxHistoryLimit);
1510	        limit = kMaxHistoryLimit;
1511	    }
1512	
1513	    std::string result = "[]";
1514	    if (ctx_ && ctx_->db_mgr && ctx_->db_mgr->isOpen()) {
1515	        result = ctx_->db_mgr->queryHistory(iface_filter, start_time, end_time, limit);
1516	    } else {
1517	        result = "{\"error\":\"database not available\"}";
1518	    }
1519	
1520	    DBusMessage* reply = dbus_message_new_method_return(msg);
1521	    if (!reply) return false;
1522	
1523	    DBusMessageIter reply_args;
1524	    dbus_message_iter_init_append(reply, &reply_args);
1525	    const char* s = result.c_str();
1526	    dbus_message_iter_append_basic(&reply_args, DBUS_TYPE_STRING, &s);
1527	    dbus_connection_send(conn, reply, nullptr);
1528	    dbus_connection_flush(conn);
1529	    dbus_message_unref(reply);
1530	    return true;
1531	}
