1764	
1765	bool DbusService::handleSetMonitorParam(DBusConnection* conn, DBusMessage* msg) {
1766	    LOG_INFO(LogModule::DBUS, "handleSetMonitorParam called");
1767	
1768	    // 运行时调参能改变设备行为（例如 active_probe.targets 决定它主动连接谁），
1769	    // 因此与 ExecuteAction 同级：仅 root 可写。
1770	    if (!requireRootCaller(conn, msg, "SetMonitorParam")) return false;
1771	
1772	    DBusError err;
1773	    dbus_error_init(&err);
1774	    const char* key = nullptr;
1775	    const char* value = nullptr;
1776	
1777	    if (!dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &key,
1778	                               DBUS_TYPE_STRING, &value, DBUS_TYPE_INVALID)) {
1779	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam arg error: " << err.message);
1780	        dbus_error_free(&err);
1781	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Invalid arguments (expect: string key, string value)");
1782	        dbus_connection_send(conn, reply, nullptr);
1783	        dbus_message_unref(reply);
1784	        return false;
1785	    }
1786	    if (!key || !value) {
1787	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Null key or value");
1788	        dbus_connection_send(conn, reply, nullptr);
1789	        dbus_message_unref(reply);
1790	        return false;
1791	    }
1792	
1793	    LOG_INFO(LogModule::DBUS, "SetMonitorParam: " << key << " = " << value);
1794	    std::string cfg_err;
1795	
1796	    // TRIAL 中本地调参会让回滚基线失真（trial 期间改过的 key，回滚时
1797	    // prior_values 已含云端的 trial 前值；本地再写一遍，等回滚来时被
1798	    // 覆盖成 trial 前 —— 等于把运维在 trial 期间的合法改动吞掉）。
1799	    // 因此 TRIAL 中显式拒绝本地写，等 confirm/rollback 后再放开。
1800	    if (ctx_->config_txn &&
1801	        ctx_->config_txn->state() == weaknet_dbus::ConfigState::TRIAL) {
1802	        cfg_err = "trial_in_progress";
1803	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
1804	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
1805	        dbus_connection_send(conn, reply, nullptr);
1806	        dbus_message_unref(reply);
1807	        return false;
1808	    }
1809	
1810	    // ctx_->cfg 是线程安全配置，setMonitorParam 内部对目标字段做校验+原子写入
1811	    if (!setMonitorParam(&ctx_->cfg, key, value, &cfg_err)) {
1812	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
1813	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
1814	        dbus_connection_send(conn, reply, nullptr);
1815	        dbus_message_unref(reply);
1816	        return false;
1817	    }
1818	
1819	    // 若修改的是 active_probe 参数，立即重载配置并下发至运行中的探测实例，使改动实时生效
1820	    if (std::string(key).rfind("active_probe.", 0) == 0) {
1821	        applyActiveProbeConfig(ctx_);
1822	    }
1823	
1824	    LOG_INFO(LogModule::DBUS, "SetMonitorParam applied: " << key << " = " << value);
1825	
1826	    // 本地调参同样是一条 L1 事实，且是唯一一条"未经云端队列"的写入路径：
1827	    // 云端没有 network_pending_actions 记录可关联，只能由回执自带
1828	    // key/value/generation，才能落成一行 execution_origin=LOCAL_OPERATION 的
1829	    // outcome，与云端下发动作同表可查（否则本地改动在云端只表现为
1830	    // config_generation 跳变，无从判断改了什么）。
1831	    // 放在成功分支之后——上面失败处均已 return，能走到这里状态确实已变更。
1832	    if (ctx_ && ctx_->edge_exporter) {
1833	        ctx_->edge_exporter->emitLocalConfigChange(
1834	            key, value, "local_dbus_set", ctx_->cfg.config_generation.load());
1835	    }
1836	
1837	    // 返回成功
1838	    DBusMessage* reply = dbus_message_new_method_return(msg);
1839	    if (!reply) return false;
1840	
1841	    const char* status = "ok";
1842	    DBusMessageIter reply_args;
1843	    dbus_message_iter_init_append(reply, &reply_args);
1844	    dbus_message_iter_append_basic(&reply_args, DBUS_TYPE_STRING, &status);
1845	    dbus_connection_send(conn, reply, nullptr);
1846	    dbus_connection_flush(conn);
1847	    dbus_message_unref(reply);
1848	    return true;
1849	}
