1935	    dbus_connection_flush(conn);
1936	    dbus_message_unref(reply);
1937	    return true;
1938	}
1939	
1940	bool DbusService::handleGetMonitorStatus(DBusConnection* conn, DBusMessage* msg) {
1941	    DBusError err;
1942	    dbus_error_init(&err);
1943	    const char* name = nullptr;
1944	    if (!monitorNameArg(msg, &name, &err)) {
1945	        const char* text = dbus_error_is_set(&err) ? err.message : "missing monitor name";
1946	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", text);
1947	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
1948	        dbus_error_free(&err);
1949	        return false;
1950	    }
1951	    MonitorStatus status;
1952	    if (!ctx_ || !ctx_->monitor_manager || !ctx_->monitor_manager->status(name, &status)) {
1953	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "unknown monitor");
1954	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
1955	        return false;
1956	    }
1957	    std::string result = monitorStatusJson(status);
1958	    DBusMessage* reply = dbus_message_new_method_return(msg);
1959	    if (!reply) return false;
1960	    DBusMessageIter iter;
1961	    dbus_message_iter_init_append(reply, &iter);
1962	    const char* value = result.c_str();
1963	    dbus_message_iter_append_basic(&iter, DBUS_TYPE_STRING, &value);
1964	    dbus_connection_send(conn, reply, nullptr);
1965	    dbus_connection_flush(conn);
1966	    dbus_message_unref(reply);
1967	    return true;
1968	}
1969	
1970	bool DbusService::handleEnableMonitor(DBusConnection* conn, DBusMessage* msg) {
1971	    return handleMonitorOperation(conn, msg, "enable");
1972	}
1973	
1974	bool DbusService::handleDisableMonitor(DBusConnection* conn, DBusMessage* msg) {
1975	    return handleMonitorOperation(conn, msg, "disable");
1976	}
1977	
1978	bool DbusService::handleRestartMonitor(DBusConnection* conn, DBusMessage* msg) {
1979	    return handleMonitorOperation(conn, msg, "restart");
1980	}
1981	
1982	
1983	// The lifecycle handlers share the same argument validation and reply contract.
1984	bool DbusService::handleMonitorOperation(DBusConnection* conn, DBusMessage* msg,
1985	                                         const char* operation) {
1986	    // enable/disable/restart 会改变评估管线的运行态（例如停掉 quality 即静默
1987	    // 关闭整套评估），与运行时调参同级：仅 root 可写。
1988	    if (!requireRootCaller(conn, msg, operation)) return false;
1989	
1990	    DBusError err;
1991	    dbus_error_init(&err);
1992	    const char* name = nullptr;
1993	    if (!monitorNameArg(msg, &name, &err)) {
1994	        const char* text = dbus_error_is_set(&err) ? err.message : "missing monitor name";
1995	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", text);
1996	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
1997	        dbus_error_free(&err);
1998	        return false;
1999	    }
2000	    if (!ctx_ || !ctx_->monitor_manager) {
2001	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "monitor manager unavailable");
2002	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
2003	        return false;
2004	    }
2005	    std::string error;
2006	    bool ok = false;
2007	    if (std::string(operation) == "enable") ok = ctx_->monitor_manager->enable(name, &error);
2008	    else if (std::string(operation) == "disable") ok = ctx_->monitor_manager->disable(name, &error);
2009	    else ok = ctx_->monitor_manager->restart(name, &error);
2010	    if (!ok) {
2011	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", error.c_str());
2012	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
2013	        return false;
2014	    }
2015	    MonitorStatus status;
2016	    ctx_->monitor_manager->status(name, &status);
2017	    std::string result = monitorStatusJson(status);
2018	    DBusMessage* reply = dbus_message_new_method_return(msg);
2019	    if (!reply) return false;
2020	    DBusMessageIter iter;
2021	    dbus_message_iter_init_append(reply, &iter);
2022	    const char* value = result.c_str();
2023	    dbus_message_iter_append_basic(&iter, DBUS_TYPE_STRING, &value);
2024	    dbus_connection_send(conn, reply, nullptr);
2025	    dbus_connection_flush(conn);
2026	    dbus_message_unref(reply);
2027	    return true;
2028	}
2029	
2030	bool DbusService::handleSaveMonitorOverrides(DBusConnection* conn, DBusMessage* msg) {
2031	    // 持久化运行时启停状态，影响后续启动行为：仅 root 可写。
2032	    if (!requireRootCaller(conn, msg, "SaveMonitorOverrides")) return false;
2033	
2034	    std::string error;
2035	    if (!ctx_ || !ctx_->monitor_manager || !ctx_->monitor_manager->saveOverrides(&error)) {
2036	        DBusMessage* reply = dbus_message_new_error(
2037	            msg, "com.example.WeakNet.Error",
2038	            error.empty() ? "failed to save monitor overrides" : error.c_str());
2039	        if (reply) { dbus_connection_send(conn, reply, nullptr); dbus_message_unref(reply); }
2040	        return false;
2041	    }
2042	    const char* result = "ok";
2043	    DBusMessage* reply = dbus_message_new_method_return(msg);
2044	    if (!reply) return false;
2045	    DBusMessageIter iter;
2046	    dbus_message_iter_init_append(reply, &iter);
2047	    dbus_message_iter_append_basic(&iter, DBUS_TYPE_STRING, &result);
2048	    dbus_connection_send(conn, reply, nullptr);
2049	    dbus_connection_flush(conn);
2050	    dbus_message_unref(reply);
2051	    return true;
2052	}
2053	
2054	}  // namespace weaknet_dbus
