 */
bool DbusService::handleGetSkbDropStats(DBusConnection* conn, DBusMessage* msg) {
    LOG_INFO(LogModule::DBUS, "handleGetSkbDropStats called");
    DBusMessage* reply = dbus_message_new_method_return(msg);
    if (!reply) {
        LOG_ERROR(LogModule::DBUS, "handleGetSkbDropStats: failed to create reply");
        return false;
    }

    std::ostringstream json;
    bool has_stats = false;
    DropStatsSummary summary;
    if (ctx_) {
        std::shared_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
        if (ctx_->skb_drop_monitor) {
            summary = ctx_->skb_drop_monitor->getDropStats();
            has_stats = true;
        }
